    bronze_gardentransplantingdibber = { name = "Bronast sadilnik za presajanje", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast sadilnik za presajanje za vrtnarje." },
    silver_gardentransplantingdibber = { name = "Srebrn sadilnik za presajanje", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn sadilnik za presajanje za vrtnarje." },
