    jewel_set_gardentransplantingdibber = { name = "Draguljast sadilnik za presajanje", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast sadilnik za presajanje za vrtnarje." },
