}
GardenTransplantingDibberMaker.ironStock=14; GardenTransplantingDibberMaker.bronzeStock=12; GardenTransplantingDibberMaker.woodStock=16; GardenTransplantingDibberMaker.leatherStock=8; GardenTransplantingDibberMaker.silverStock=8; GardenTransplantingDibberMaker.goldStock=6; GardenTransplantingDibberMaker.jewelStock=4; GardenTransplantingDibberMaker.pearlStock=4
GardenTransplantingDibberMaker.productStock = {}; GardenTransplantingDibberMaker.buildings = {}; GardenTransplantingDibberMaker.maker = nil; GardenTransplantingDibberMaker.activeMaking = {}; GardenTransplantingDibberMaker.totalProducts = 0; GardenTransplantingDibberMaker.dayTimer = 0
function GardenTransplantingDibberMaker.init() GardenTransplantingDibberMaker.ironStock=14; GardenTransplantingDibberMaker.bronzeStock=12; GardenTransplantingDibberMaker.woodStock=16; GardenTransplantingDibberMaker.leatherStock=8; GardenTransplantingDibberMaker.silverStock=8; GardenTransplantingDibberMaker.goldStock=6; GardenTransplantingDibberMaker.jewelStock=4; GardenTransplantingDibberMaker.pearlStock=4; GardenTransplantingDibberMaker.productStock={}; GardenTransplantingDibberMaker.buildings={}; GardenTransplantingDibberMaker.maker=nil; GardenTransplantingDibberMaker.activeMaking={}; GardenTransplantingDibberMaker.totalProducts=0; GardenTransplantingDibberMaker.dayTimer=0; print("[GardenTransplantingDibberMaker] Royal Garden Transplanting Dibber Maker System initialized (6 products, 4 buildings)") end
function GardenTransplantingDibberMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenTransplantingDibberMaker.maker={name=n or ("Sadilnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sadilnikar najet: %s (spretnost: %d)",GardenTransplantingDibberMaker.maker.name,s),"success") end; return true end
function GardenTransplantingDibberMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenTransplantingDibberMaker.build(id) local ok,e=GardenTransplantingDibberMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenTransplantingDibberMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenTransplantingDibberMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenTransplantingDibberMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenTransplantingDibberMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenTransplantingDibberMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenTransplantingDibberMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenTransplantingDibberMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenTransplantingDibberMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenTransplantingDibberMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenTransplantingDibberMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenTransplantingDibberMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenTransplantingDibberMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenTransplantingDibberMaker.buildings==0 then return false,"Potrebna sadilna delavnica" end; if not GardenTransplantingDibberMaker.maker then return false,"Potreben sadilnikar" end; return true end
function GardenTransplantingDibberMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenTransplantingDibberMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenTransplantingDibberMaker.ironStock=GardenTransplantingDibberMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenTransplantingDibberMaker.bronzeStock=GardenTransplantingDibberMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenTransplantingDibberMaker.woodStock=GardenTransplantingDibberMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenTransplantingDibberMaker.leatherStock=GardenTransplantingDibberMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenTransplantingDibberMaker.silverStock=GardenTransplantingDibberMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenTransplantingDibberMaker.goldStock=GardenTransplantingDibberMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenTransplantingDibberMaker.jewelStock=GardenTransplantingDibberMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenTransplantingDibberMaker.pearlStock=GardenTransplantingDibberMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenTransplantingDibberMaker.maker then t=math.max(1,t-math.floor(GardenTransplantingDibberMaker.maker.skill/13)) end; table.insert(GardenTransplantingDibberMaker.activeMaking,{id="gardentransplantingdibber_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenTransplantingDibberMaker.completeMaking(m) local q=1.0+(GardenTransplantingDibberMaker.getQualityBonus()/100); if GardenTransplantingDibberMaker.maker then q=q+(GardenTransplantingDibberMaker.maker.skill/140) end; q=math.min(2.5,q); GardenTransplantingDibberMaker.productStock[m.productType]=(GardenTransplantingDibberMaker.productStock[m.productType] or 0)+m.quantity; GardenTransplantingDibberMaker.totalProducts=GardenTransplantingDibberMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenTransplantingDibberMaker.maker then GardenTransplantingDibberMaker.maker.itemsMade=GardenTransplantingDibberMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenTransplantingDibberMaker.maker.skill=math.min(100,GardenTransplantingDibberMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sadilnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardentransplantingdibber.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenTransplantingDibberMaker.update(dt) if not _G.state then return end; GardenTransplantingDibberMaker.dayTimer=GardenTransplantingDibberMaker.dayTimer+dt; if GardenTransplantingDibberMaker.dayTimer>=30 then GardenTransplantingDibberMaker.dayTimer=0; for i=#GardenTransplantingDibberMaker.activeMaking,1,-1 do local m=GardenTransplantingDibberMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenTransplantingDibberMaker.completeMaking(m); table.remove(GardenTransplantingDibberMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenTransplantingDibberMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenTransplantingDibberMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenTransplantingDibberMaker.getStats() return {ironStock=GardenTransplantingDibberMaker.ironStock,bronzeStock=GardenTransplantingDibberMaker.bronzeStock,woodStock=GardenTransplantingDibberMaker.woodStock,leatherStock=GardenTransplantingDibberMaker.leatherStock,silverStock=GardenTransplantingDibberMaker.silverStock,goldStock=GardenTransplantingDibberMaker.goldStock,jewelStock=GardenTransplantingDibberMaker.jewelStock,pearlStock=GardenTransplantingDibberMaker.pearlStock,productStock=GardenTransplantingDibberMaker.productStock,numBuildings=#GardenTransplantingDibberMaker.buildings,hasMaker=GardenTransplantingDibberMaker.maker~=nil,makerName=GardenTransplantingDibberMaker.maker and GardenTransplantingDibberMaker.maker.name or "—",makerSkill=GardenTransplantingDibberMaker.maker and GardenTransplantingDibberMaker.maker.skill or 0,activeMaking=#GardenTransplantingDibberMaker.activeMaking,totalProducts=GardenTransplantingDibberMaker.totalProducts} end
return GardenTransplantingDibberMaker
